def calculate_accuracy(y_true, y_pred):
    correct = sum(1 for t, p in zip(y_true, y_pred) if t == p)
    return correct / len(y_true) if len(y_true) > 0 else 0

def confusion_matrix(y_true, y_pred, labels=None):
    if labels is None:
        labels = sorted(set(y_true) | set(y_pred))

    n = len(labels)
    cm = [[0 for _ in range(n)] for _ in range(n)]

    label_to_idx = {label: i for i, label in enumerate(labels)}

    for t, p in zip(y_true, y_pred):
        true_idx = label_to_idx[t]
        pred_idx = label_to_idx[p]
        cm[true_idx][pred_idx] += 1

    return cm

import numpy as np

def softmax(x):
    exp_x = np.exp(x - np.max(x))  # For numerical stability
    return exp_x / np.sum(exp_x)

import numpy as np

def sigmoid(x):
    return 1 / (1 + np.exp(-x))

def logistic_regression_predict(X, weights, bias):
    linear_output = np.dot(X, weights) + bias
    probabilities = sigmoid(linear_output)
    predictions = (probabilities >= 0.5).astype(int)
    return predictions, probabilities

def binary_confusion_matrix(y_true, y_pred):
    tp = sum((t == 1 and p == 1) for t, p in zip(y_true, y_pred))
    tn = sum((t == 0 and p == 0) for t, p in zip(y_true, y_pred))
    fp = sum((t == 0 and p == 1) for t, p in zip(y_true, y_pred))
    fn = sum((t == 1 and p == 0) for t, p in zip(y_true, y_pred))

    return {
        'TP': tp,
        'TN': tn,
        'FP': fp,
        'FN': fn,
        'matrix': [[tn, fp], [fn, tp]]
    }

