import numpy as np

class SimpleDecisionTree:
    def __init__(self, max_depth=5, min_samples_split=2):
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
        self.tree = None

    def gini_impurity(self, y):
        if len(y) == 0:
            return 0
        p1 = np.sum(y) / len(y)
        p0 = 1 - p1
        return 1 - (p0**2 + p1**2)

    def best_split(self, X, y):
        best_gini = float('inf')
        best_split = None

        for feature_idx in range(X.shape[1]):
            for threshold in np.unique(X[:, feature_idx]):
                left_mask = X[:, feature_idx] <= threshold
                right_mask = ~left_mask

                if np.sum(left_mask) == 0 or np.sum(right_mask) == 0:
                    continue

                gini_left = self.gini_impurity(y[left_mask])
                gini_right = self.gini_impurity(y[right_mask])

                weighted_gini = (np.sum(left_mask) * gini_left + 
                               np.sum(right_mask) * gini_right) / len(y)

                if weighted_gini < best_gini:
                    best_gini = weighted_gini
                    best_split = (feature_idx, threshold)

        return best_split

    def build_tree(self, X, y, depth=0):
        if (depth >= self.max_depth or 
            len(y) < self.min_samples_split or 
            len(np.unique(y)) == 1):
            return np.mean(y) >= 0.5  # Return majority class

        split = self.best_split(X, y)
        if split is None:
            return np.mean(y) >= 0.5

        feature_idx, threshold = split
        left_mask = X[:, feature_idx] <= threshold
        right_mask = ~left_mask

        node = {
            'feature': feature_idx,
            'threshold': threshold,
            'left': self.build_tree(X[left_mask], y[left_mask], depth+1),
            'right': self.build_tree(X[right_mask], y[right_mask], depth+1)
        }

        return node

    def fit(self, X, y):
        self.tree = self.build_tree(np.array(X), np.array(y))

    def predict_one(self, x, node):
        if not isinstance(node, dict):
            return node

        if x[node['feature']] <= node['threshold']:
            return self.predict_one(x, node['left'])
        else:
            return self.predict_one(x, node['right'])

    def predict(self, X):
        return [self.predict_one(x, self.tree) for x in X]
